INSERT INTO `services_i18n` (`id`,`service_id`,`locale`,`slug`,`name`,`summary`,`content`,`image_alt`,`meta_title`,`meta_description`,`meta_keywords`,`created_at`,`updated_at`) VALUES ('3bad1c63-1d61-5ddb-9486-22a51c851608','13db937a-1c77-5821-94d8-cacd14ee3a87','tr','b2b-urun-katalogu-teklif-talep-sistemi','B2B Ürün Kataloğu ve Teklif Talep Sistemi','Ürünlerinizi kurumsal alıcılara teknik özellikleriyle sunan, çok dilli, filtrelenebilir katalog ve teklif talebi (RFQ) akışı olan B2B web sitesi.','{"html": "<p>B2B alıcı fiyat listesiyle değil, teknik özellik ve teklifle karar verir. B2B ürün kataloğu, ürünlerinizi kurumsal alıcılara bu dille sunan ve her ürün sayfasını bir teklif talebine bağlayan web sitesidir. GZL Teknoloji olarak bu siteleri üretici ve tedarikçilerin gerçek satış akışına göre kuruyoruz.</p><h2>B2B ürün kataloğu nedir?</h2><p>Bir e-ticaret sitesinden farkı, satışın sepette değil görüşmede kapanmasıdır. Alıcı ürünü bulur, teknik değerlerini karşılaştırır, belgelerini indirir ve teklif ister. Katalog bu yolu kısaltır; teklif talepleri de e-posta kutularında kaybolmak yerine panelde toplanır.</p><h2>Neler teslim ediyoruz?</h2><ul><li>Kategorili, filtrelenebilir ürün kataloğu ve teknik özellik tabloları</li><li>Her ürün sayfasında teklif talebi (RFQ) formu ve talep yönetimi</li><li>Çok dilli yapı; dil başına ayrı adres ve doğru hreflang eşleşmesi</li><li>Katalog, teknik doküman ve sertifika indirme alanları</li><li>İçeriğin tamamını yöneten panel: ürün, kategori, görsel ve sayfalar</li><li>Teknik SEO ve yapay zekâ aramaları için yapılandırılmış veri, site haritası ve llms.txt</li></ul><h2>Nasıl çalışıyoruz?</h2><ol><li>Ürün ağacı, teknik alanlar ve alıcı profili çıkarılır.</li><li>Mevcut ürün verisi (Excel veya eski site) aktarılır.</li><li>Katalog ve teklif akışı tasarlanıp geliştirilir.</li><li>Dil, hız ve arama kontrolleriyle yayına alınır.</li></ol><h2>Kimler için uygun?</h2><ul><li>İhracat yapan ve çok dilli katalog isteyen üreticiler</li><li>Teknik ürün satan tedarikçi ve distribütörler</li><li>Teklif taleplerini tek yerde toplamak isteyen satış ekipleri</li></ul><p>Online sepet ve ödeme gerekiyorsa e-ticaret altyapısıyla başlamak daha doğrudur: <a href=\\"/tr/hizmetler/modern-e-ticaret-sitesi\\">Modern e-ticaret sitesi</a>.</p><h2>Fiyat ve süre</h2><p>Fiyat ve süre ürün sayısına, dil sayısına ve aktarılacak veri kapsamına göre belirlenir; ihtiyacınızı dinledikten sonra yazılı teklif veriyoruz.</p><h2>Sıkça Sorulan Sorular</h2><h3>Fiyatları sitede göstermek zorunda mıyız?</h3><p>Hayır. Fiyat gizli kalabilir; alıcı teklif ister, talep panelinize düşer.</p><h3>Ürünleri kendimiz ekleyebilir miyiz?</h3><p>Evet. Ürün, kategori, görsel ve doküman yönetimi panelden yapılır.</p><h3>Mevcut sitemizin adresleri korunur mu?</h3><p>Evet. Adres değişiyorsa yönlendirme haritası hazırlanır; arama motorlarındaki mevcut değer korunur.</p><p>İlgili sayfalar: <a href=\\"/tr/portfolyo\\">Portföy</a> · <a href=\\"/tr/hizmetler/kurumsal-web-sitesi\\">Kurumsal web sitesi</a> · <a href=\\"/tr/iletisim\\">İletişim</a></p>", "source": "hizmetler-2026-10b"}','B2B ürün kataloğu ve teklif talep sistemi örnekleri','B2B Ürün Kataloğu ve Teklif Talep Sistemi | Guezel Web Design','Üreticiler ve tedarikçiler için çok dilli B2B ürün kataloğu: teknik özellikler, filtreleme, teklif talebi (RFQ), yönetim paneli ve SEO/GEO altyapısı.','b2b ürün kataloğu, teklif talep sistemi, rfq, çok dilli katalog sitesi',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`name`=VALUES(`name`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`image_alt`=VALUES(`image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`meta_keywords`=VALUES(`meta_keywords`),`updated_at`=NOW(3);
INSERT INTO `service_images_i18n` (`id`,`image_id`,`locale`,`title`,`alt`,`caption`,`created_at`,`updated_at`) VALUES ('f5a6ee1d-ea9b-5c47-8f2a-df65c5784de5','721b2c4e-ad84-5ed4-8911-d9c56ad60d97','tr','B2B Ürün Kataloğu ve Teklif Talep Sistemi','B2B ürün kataloğu ve teklif talep sistemi örnekleri',NULL,NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`alt`=VALUES(`alt`),`updated_at`=NOW(3);
INSERT INTO `services_i18n` (`id`,`service_id`,`locale`,`slug`,`name`,`summary`,`content`,`image_alt`,`meta_title`,`meta_description`,`meta_keywords`,`created_at`,`updated_at`) VALUES ('83f87092-41a2-5c55-b21a-66b81adb3de3','13db937a-1c77-5821-94d8-cacd14ee3a87','en','b2b-product-catalog-quote-request-system','B2B Product Catalog and Quote Request System','A multilingual B2B website that presents your products to business buyers with technical specifications, filterable catalog pages and a request-for-quote (RFQ) flow.','{"html": "<p>B2B buyers decide on technical specifications and quotes, not on a price list. A B2B product catalog presents your products in that language and connects every product page to a quote request. We build these sites around the real sales process of manufacturers and suppliers.</p><h2>What is a B2B product catalog?</h2><p>Unlike an online shop, the sale closes in a conversation, not in a basket. Buyers find the product, compare its specifications, download documents and request a quote. The catalog shortens that path, and quote requests land in a panel instead of getting lost in inboxes.</p><h2>What we deliver</h2><ul><li>Categorised, filterable product catalog with specification tables</li><li>A request-for-quote (RFQ) form on every product page plus request management</li><li>Multilingual structure with separate URLs per language and correct hreflang</li><li>Downloads for catalogs, technical documents and certificates</li><li>A panel that manages all content: products, categories, images and pages</li><li>Structured data, sitemap and llms.txt for technical SEO and AI search</li></ul><h2>How we work</h2><ol><li>We map the product tree, technical fields and buyer profile.</li><li>Existing product data (Excel or old site) is migrated.</li><li>The catalog and quote flow are designed and built.</li><li>We launch after language, speed and search checks.</li></ol><h2>Who is it for?</h2><ul><li>Exporting manufacturers that need a multilingual catalog</li><li>Suppliers and distributors of technical products</li><li>Sales teams that want all quote requests in one place</li></ul><p>If you need a basket and online payment, start with an e-commerce platform instead: <a href=\\"/en/services/modern-e-ticaret-sitesi\\">Modern e-commerce website</a>.</p><h2>Pricing and timeline</h2><p>Price and timeline depend on the number of products and languages and the data to migrate; we send a written quote after we understand your needs.</p><h2>Frequently asked questions</h2><h3>Do we have to show prices?</h3><p>No. Prices can stay hidden; buyers request a quote and it lands in your panel.</p><h3>Can we add products ourselves?</h3><p>Yes. Products, categories, images and documents are managed in the panel.</p><h3>Will our existing URLs be kept?</h3><p>Yes. If URLs change we prepare a redirect map so existing search rankings are preserved.</p><p>Related pages: <a href=\\"/en/work\\">Portfolio</a> · <a href=\\"/en/services/kurumsal-web-sitesi\\">Corporate website</a> · <a href=\\"/en/contact\\">Contact</a></p>", "source": "hizmetler-2026-10b"}','Examples of B2B product catalog and quote request systems','B2B Product Catalog and Quote Request System | Guezel Web Design','Multilingual B2B product catalog for manufacturers and suppliers: technical specs, filters, request for quote (RFQ), admin panel and SEO/GEO foundations.','b2b product catalog, quote request system, rfq, multilingual catalog website',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`name`=VALUES(`name`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`image_alt`=VALUES(`image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`meta_keywords`=VALUES(`meta_keywords`),`updated_at`=NOW(3);
INSERT INTO `service_images_i18n` (`id`,`image_id`,`locale`,`title`,`alt`,`caption`,`created_at`,`updated_at`) VALUES ('cb701f1a-a0ff-5490-83ed-f894860fedf7','721b2c4e-ad84-5ed4-8911-d9c56ad60d97','en','B2B Product Catalog and Quote Request System','Examples of B2B product catalog and quote request systems',NULL,NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`alt`=VALUES(`alt`),`updated_at`=NOW(3);
INSERT INTO `services_i18n` (`id`,`service_id`,`locale`,`slug`,`name`,`summary`,`content`,`image_alt`,`meta_title`,`meta_description`,`meta_keywords`,`created_at`,`updated_at`) VALUES ('19c26b51-3bfa-5f35-a024-0717ed09fc6e','13db937a-1c77-5821-94d8-cacd14ee3a87','de','b2b-produktkatalog-angebotsanfrage-system','B2B-Produktkatalog und Angebotsanfrage-System','Eine mehrsprachige B2B-Website, die Ihre Produkte Geschäftskunden mit technischen Daten, filterbaren Katalogseiten und einem Angebotsanfrage-Ablauf (RFQ) präsentiert.','{"html": "<p>B2B-Einkäufer entscheiden nach technischen Daten und Angeboten, nicht nach einer Preisliste. Ein B2B-Produktkatalog präsentiert Ihre Produkte genau so und verbindet jede Produktseite mit einer Angebotsanfrage. Wir bauen diese Websites entlang des tatsächlichen Vertriebsprozesses von Herstellern und Lieferanten.</p><h2>Was ist ein B2B-Produktkatalog?</h2><p>Anders als im Onlineshop schließt der Verkauf im Gespräch, nicht im Warenkorb. Einkäufer finden das Produkt, vergleichen technische Werte, laden Unterlagen herunter und fordern ein Angebot an. Der Katalog verkürzt diesen Weg, und Anfragen landen im Panel statt in Postfächern.</p><h2>Was wir liefern</h2><ul><li>Kategorisierter, filterbarer Produktkatalog mit technischen Datentabellen</li><li>Angebotsanfrage (RFQ) auf jeder Produktseite samt Anfrageverwaltung</li><li>Mehrsprachige Struktur mit eigenen URLs je Sprache und korrektem hreflang</li><li>Downloads für Kataloge, technische Unterlagen und Zertifikate</li><li>Ein Panel für alle Inhalte: Produkte, Kategorien, Bilder und Seiten</li><li>Strukturierte Daten, Sitemap und llms.txt für technisches SEO und KI-Suche</li></ul><h2>So arbeiten wir</h2><ol><li>Produktbaum, technische Felder und Käuferprofil werden erfasst.</li><li>Vorhandene Produktdaten (Excel oder alte Website) werden übernommen.</li><li>Katalog und Angebotsablauf werden gestaltet und entwickelt.</li><li>Livegang nach Sprach-, Geschwindigkeits- und Suchprüfungen.</li></ol><h2>Für wen geeignet?</h2><ul><li>Exportierende Hersteller mit Bedarf an mehrsprachigen Katalogen</li><li>Lieferanten und Distributoren technischer Produkte</li><li>Vertriebsteams, die alle Angebotsanfragen an einem Ort bündeln wollen</li></ul><p>Wenn Sie Warenkorb und Online-Zahlung brauchen, ist ein Onlineshop der bessere Start: <a href=\\"/de/leistungen/modern-e-ticaret-sitesi\\">Moderner Onlineshop</a>.</p><h2>Preis und Dauer</h2><p>Preis und Dauer richten sich nach Produkt- und Sprachanzahl sowie den zu übernehmenden Daten; nach einem Gespräch erhalten Sie ein schriftliches Angebot.</p><h2>Häufige Fragen</h2><h3>Müssen wir Preise anzeigen?</h3><p>Nein. Preise können verborgen bleiben; Einkäufer fordern ein Angebot an, das in Ihrem Panel landet.</p><h3>Können wir Produkte selbst anlegen?</h3><p>Ja. Produkte, Kategorien, Bilder und Dokumente werden im Panel verwaltet.</p><h3>Bleiben unsere bisherigen URLs erhalten?</h3><p>Ja. Ändern sich Adressen, erstellen wir eine Weiterleitungstabelle, damit bestehende Rankings erhalten bleiben.</p><p>Verwandte Seiten: <a href=\\"/de/projekte\\">Projekte</a> · <a href=\\"/de/leistungen/kurumsal-web-sitesi\\">Unternehmenswebsite</a> · <a href=\\"/de/kontakt\\">Kontakt</a></p>", "source": "hizmetler-2026-10b"}','Beispiele für B2B-Produktkataloge mit Angebotsanfrage','B2B-Produktkatalog und Angebotsanfrage-System','Mehrsprachiger B2B-Produktkatalog für Hersteller und Lieferanten: technische Daten, Filter, Angebotsanfrage (RFQ), Admin-Panel und SEO/GEO-Grundlagen.','b2b produktkatalog, angebotsanfrage system, rfq, mehrsprachige katalog website',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`name`=VALUES(`name`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`image_alt`=VALUES(`image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`meta_keywords`=VALUES(`meta_keywords`),`updated_at`=NOW(3);
